"""Editorial question review for linguistics and art/civilization."""

from review_angle_plans import audit, revise_domain


LANGUAGE = """history_origins|A Language's Documented History|What do dated records show about one language's change?|Compare texts, recordings, contact history, and limits of surviving evidence.
famous_examples|A Linguistic Feature in Context|How does one widely cited sound, word, or grammar pattern actually work?|Use attested examples from named speakers or corpora, not an exoticizing anecdote.
hidden_stories|Speakers Behind the Description|Whose knowledge and labor produced one grammar, dictionary, or corpus?|Trace contributor credits, consent, and community access.
beginner_explainers|How Linguists Describe Speech|How do researchers record and analyze one everyday language pattern?|Follow data collection, transcription, comparison, and speaker feedback.
advanced_concepts|Variation Within a Language|How do region, setting, age, and identity affect one measured feature?|Compare matched samples without treating one variety as deficient.
mysteries_unsolved_cases|An Uncertain Word Origin|Which proposed histories of one word fit the dated evidence?|Compare early attestations, sound change, contact, and gaps.
technology_innovation|A Tool for Language Documentation|What did one recording or transcription technology make possible?|Compare accuracy, access, cost, consent, and data custody.
people_personalities|A Speaker, Teacher, or Researcher|How did a named contributor shape the record of one language?|Use attributed work and avoid a single-savior narrative.
major_events|A Policy Changes Language Use|What changed after one school, media, or official-language decision?|Compare implementation, speaker experience, and usage evidence.
how_it_works|From Recording to Dictionary Entry|How is a word documented, analyzed, translated, and approved?|Trace one consented example and community review.
rise_fall|Shifting Language Domains|Where did use of one language expand or contract over a defined period?|Measure contexts of use and intergenerational transmission, not just speaker counts.
then_vs_now|One Feature Across Generations|Did a pronunciation or grammatical pattern change?|Compare dated recordings with sampling and recording-method limits.
future_developments|A Community-Led Language Project|Which resources and decisions would support a stated language goal?|Name community priorities, teaching capacity, data rights, and measurable outcomes.
myths_vs_facts|A Language Myth Checked|Does a claim that a language is primitive, pure, or dying match evidence?|Define terms, assess actual use, and foreground speaker perspectives.
documentary_stories|A Word's Recorded Journey|How did one word move through speakers, texts, and regions?|Build a dated account while separating attested links from conjecture.
creative_brief|Choosing a Language Question|Whose language practice will a story document and for whom?|Set community partnership, consent, audience, and use of recordings.
materials_and_tools|Building a Speech Record|Which microphones, annotations, scripts, and archives support one documentation project?|Compare technical choices, accessibility, ownership, and preservation.
process_breakdown|One Utterance Analyzed|How does a recorded phrase become transcription, gloss, and interpretation?|Show speaker checking and uncertainty at every stage.
composition_choice|Selecting Examples Fairly|How does choosing one utterance shape a listener's impression of a variety?|Compare context, register, speaker consent, and counterexamples.
collaborative_authorship|Who Owns a Language Resource?|How did speakers, elders, teachers, and linguists divide decisions in one project?|Read agreements, credits, access rules, and community review.
adaptation_across_media|Speech, Text, and Subtitle|What is lost when one spoken performance is transcribed or translated?|Compare intonation, gesture, timing, and orthographic choices.
audience_reception|A Resource in Actual Use|Did the intended users find one language resource useful?|Use community-led evaluation, not download totals alone.
cultural_context|Words in Social Life|When does one expression have a meaning that a dictionary gloss misses?|Use speaker explanation, setting, and permitted examples.
preservation_restoration|Keeping a Recording Usable|What metadata and permissions are needed to preserve one language archive?|Check format, speaker consent, access tiers, and future community control.
rights_and_attribution|Consent for Recorded Speech|Who can authorize recording, sharing, or reuse of one speech sample?|Follow speaker and community protocols, including restricted material.
style_comparison|Two Ways of Speaking|How do two registers or varieties differ in a matched situation?|Compare actual samples without ranking correctness.
creative_failure|When a Translation Misled|What correction followed a documented mistranslation or mislabeling?|Compare original utterance, context, speaker response, and revision.
field_textual_form|A Written Form in Context|How does script or orthography represent one sound or grammatical contrast?|Compare community standards, actual usage, and alternatives.
field_performance_choice|A Speaker's Delivery|How does rhythm, emphasis, or gesture change one utterance's meaning?|Use consented audio or video and speaker interpretation.
field_audience_history|Who Was Meant to Read or Hear?|How did the audience for one text or recording change over time?|Trace publication, schooling, broadcast, and community use.
field_translation_or_adaptation|One Phrase Across Languages|Which meaning and social relationship change in translation?|Compare source, target, speaker judgment, and stated purpose.
field_critical_reception|Response to a Language Description|How did speakers and scholars critique one grammar or dictionary?|Attribute revisions and disagreements without treating external scholarship as final authority."""


ART = """history_origins|How an Art Form Took Shape|Which materials, patrons, and practices shaped one art form in a defined place?|Use dated objects, workshop evidence, and local histories without a single-inventor claim.
famous_examples|A Masterwork Reexamined|What does one celebrated work reveal about its makers and users?|Compare object analysis, commission, setting, and later interpretation.
hidden_stories|Makers Behind the Signature|Whose workshop, material, or community labor is omitted by one artist attribution?|Use contracts, technical study, and attributed accounts.
beginner_explainers|Reading an Artwork in Context|How do material, form, subject, and original setting affect meaning?|Use one named object and distinguish observation from interpretation.
advanced_concepts|Attribution Under Debate|Which evidence supports or weakens assigning one work to a maker or workshop?|Compare provenance, technique, stylistic analysis, and uncertainty.
mysteries_unsolved_cases|An Object with Uncertain Origin|Which proposed date or place for one artwork fits its materials and records?|Assess scientific tests, catalogue history, and gaps.
technology_innovation|A Material Changes Artmaking|How did one pigment, tool, or reproduction method alter production?|Compare dated works, availability, technique, and labor.
people_personalities|An Artist's Documented Choices|What do records show about one maker's intent and constraints?|Use letters, contracts, sketches, and the finished work.
major_events|An Artwork Changes Hands|What did one transfer, loss, or return change for a work and its communities?|Trace provenance, law, conservation, and public access.
how_it_works|From Commission to Finished Work|How was one object designed, made, paid for, and installed?|Use a documented case with contributors and revisions.
rise_fall|A Style's Changing Status|Why did one art form gain or lose institutional support?|Compare patronage, trade, criticism, and maker accounts.
then_vs_now|An Object Across Display Settings|How did meaning and access change when one work moved from original setting to museum?|Compare context, labels, conservation, and community response.
future_developments|A Conservation or Return Decision|What evidence and stakeholders should shape one pending object decision?|Assess condition, provenance, rights, and community priorities conditionally.
myths_vs_facts|An Artwork Legend Checked|Does a familiar story about authorship or symbolism fit the record?|Trace earliest claim and compare documents, material tests, and alternatives.
documentary_stories|One Object's Full History|How did a work move from creation through ownership, repair, and display?|Build a dated provenance and conservation timeline with gaps visible.
creative_brief|An Artist's Task|What did a commission or maker set out to achieve?|Define audience, place, materials, constraints, and surviving evidence.
materials_and_tools|What the Object Is Made Of|Which materials and tools can be identified in one work?|Read technical analysis and distinguish original from later additions.
process_breakdown|Making a Work in Stages|Which evidence reconstructs the order of one artmaking process?|Compare sketches, underdrawings, tool marks, layers, and workshop records.
composition_choice|How an Image Directs Attention|Which visual choices guide a viewer's reading of one work?|Analyze placement, color, scale, and original viewing conditions.
collaborative_authorship|Many Hands on One Work|How were design, fabrication, and finishing shared?|Use records and material evidence rather than attributing all work to a named master.
adaptation_across_media|A Motif Moves to Another Medium|What changed when one image or design became a print, textile, or digital work?|Compare technique, circulation, meaning, and rights.
audience_reception|How Viewers Understood a Work|What do dated responses tell us about an artwork's reception?|Compare critics, patrons, local users, and gaps in surviving voices.
cultural_context|An Object in Living Culture|How do present communities interpret a work tied to their heritage?|Use attributed community voices and respect restricted meanings.
preservation_restoration|A Conservation Treatment|Which interventions preserved or altered one artwork?|Compare condition reports, tests, materials, and reversibility.
rights_and_attribution|Who May Reproduce the Work?|Which legal, custodial, or community permissions govern an image's reuse?|Check jurisdiction, date, object rights, and cultural protocols.
style_comparison|Two Works, One Claimed Style|Do two objects share technique and context or only a visual resemblance?|Compare materials, dates, provenance, and makers.
creative_failure|A Work That Did Not Meet Its Brief|What documented criticism or revision followed a failed commission?|Compare stated aims, maker response, and later reception.
field_visual_composition|Image Structure in Place|How does a work's composition change when seen in its original setting?|Compare scale, light, viewpoint, and surrounding objects.
field_material_provenance|Following an Art Material|Can one pigment, stone, or fiber be traced to a source?|Check scientific analysis, trade records, and provenance limits.
field_maker_technique|A Trace of the Hand|What tool marks or layering reveal about one maker's technique?|Compare technical images, experiments, and workshop variation.
field_conservation_problem|A Material at Risk|Which deterioration process threatens one object and what treatment is justified?|Use condition monitoring, material tests, and conservator reasoning.
field_audience_context|Who Could See the Work?|How did access to one object differ among original users and modern visitors?|Compare site rules, social roles, display, and accessibility."""


if __name__ == "__main__":
    revise_domain("041", "041_languages_linguistics", LANGUAGE,
                  "Language structure, change, documentation, translation, and community use through speaker-led evidence and ethical archives.",
                  "consented recordings and transcripts, dated texts and corpora, community-approved dictionaries and grammars, language policies, speaker interviews, and archival metadata",
                  "Treat languages and varieties as systematic, not deficient. Obtain speaker and community consent, respect restricted knowledge and data rights, and distinguish attested forms from reconstruction.")
    revise_domain("042", "042_art_civilization", ART,
                  "Artworks and making traditions through materials, labor, patronage, visual form, provenance, conservation, reception, and cultural context.",
                  "collection catalogues and ownership records, object and conservation reports, maker documents, technical imaging, dated criticism, and attributed community perspectives",
                  "Verify provenance and attribution, distinguish observation from interpretation, respect cultural protocols and return claims, and label restored or reconstructed elements.")
    rows = audit()
    print(f"Plans: {len(rows)}; reviewed question designs: {sum(r['status'] == 'editorial_question_reviewed' for r in rows)}")
